SELECT id, object_id, record_id, detail_id, row_id, field_id,
       file_id, entry_id, space_id, file_name, file_size, mime_type, state, source_entry,
       creator, create_time, updater, update_time, deleted
FROM public.nocode_biz_attachment_binding
WHERE object_id = #{objectId}
AND record_id = #{recordId}
AND detail_id = #{detailId}
AND row_id = #{rowId}
AND field_id = #{fieldId}
AND deleted = 0

